from data import students, scores

totals = {}
for student_id, subject, score in scores:
    total, count = totals.get(subject, (0, 0))
    totals[subject] = (total + score, count + 1)

averages = {s: round(t / c, 1) for s, (t, c) in totals.items()}
for subject, avg in sorted(averages.items(), key=lambda x: x[1], reverse=True):
    print((subject, avg))

has_scores = {student_id for student_id, _, _ in scores}
print("no scores yet:", [name for sid, name in students if sid not in has_scores])
